function psaPort(): int { $s=stream_socket_server('tcp://127.0.0.1:0',$e,$m);if($s===false)throw new TestFailure('allocate port');$n=(string)stream_socket_get_name($s,false);fclose($s);return (int)substr($n,strrpos($n,':')+1); }
function psaStart(string $entry,array $extra=[]): array { $port=psaPort();$cmd=['/usr/bin/env','-i','FMONITOR_SHLZ_CSS_PATH='.$entry];foreach($extra as$k=>$v)$cmd[]=$k.'='.$v;$cmd=[...$cmd,PHP_BINARY,'-d','expose_php=0','-S','127.0.0.1:'.$port,dirname(__DIR__,2).'/public/router.php'];$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2));if(!is_resource($p))throw new TestFailure('start server');fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$until=microtime(true)+5;while(microtime(true)<$until){$s=@stream_socket_client("tcp://127.0.0.1:$port",$e,$m,.1);if($s!==false){fclose($s);return compact('p','pipes','port');}usleep(20000);}throw new TestFailure('server listen'); }
function psaStop(?array $s): void { if($s===null||!is_resource($s['p']))return;if(proc_get_status($s['p'])['running'])proc_terminate($s['p']);foreach([1,2]as$i)if(is_resource($s['pipes'][$i])){stream_get_contents($s['pipes'][$i]);fclose($s['pipes'][$i]);}proc_close($s['p']); }
function psaRequest(int $port,string $method,string $route): array { $s=stream_socket_client("tcp://127.0.0.1:$port",$e,$m,5);if($s===false)throw new TestFailure('connect');fwrite($s,"$method $route HTTP/1.1\r\nHost: assets.example\r\nConnection: close\r\nContent-Length: 0\r\n\r\n");stream_socket_shutdown($s,STREAM_SHUT_WR);$raw='';while(!feof($s))$raw.=(string)fread($s,65536);fclose($s);[$h,$body]=array_pad(explode("\r\n\r\n",$raw,2),2,'');$lines=explode("\r\n",$h);preg_match('/^HTTP\/\d\.\d (\d{3})/',(string)array_shift($lines),$m);$headers=[];foreach($lines as$l)if(str_contains($l,':')){[$k,$v]=explode(':',$l,2);$headers[strtolower(trim($k))][]=trim($v);}return ['status'=>(int)($m[1]??0),'headers'=>$headers,'body'=>$body]; }
function psaHeader(array $r,string $name): ?string { $v=$r['headers'][strtolower($name)]??[];return count($v)===1?$v[0]:null; }
function psaSecurity(array $r,string $why): void { $exact=['x-content-type-options'=>'nosniff','referrer-policy'=>'no-referrer','x-frame-options'=>'DENY','content-security-policy'=>"default-src 'none'; style-src 'self'; img-src 'self'; font-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",'permissions-policy'=>'camera=(), microphone=(), geolocation=()','cross-origin-opener-policy'=>'same-origin','cache-control'=>'no-store','host'=>'assets.example'];foreach($exact as$n=>$v)assertSameValue($v,psaHeader($r,$n),$why.' '.$n);foreach(['set-cookie','access-control-allow-origin','server','x-powered-by','www-authenticate']as$n)assertSameValue(null,psaHeader($r,$n),$why.' forbids '.$n); }
function psaExact(array $r,int $status,string $type,string $body,string $why,array $extra=[]): void { assertSameValue([$status,$type,(string)strlen($body),$body],[$r['status'],psaHeader($r,'content-type'),psaHeader($r,'content-length'),$r['body']],$why);foreach($extra as$n=>$v)assertSameValue($v,psaHeader($r,$n),$why.' '.$n);psaSecurity($r,$why); }
function psaGetHead(int $port,string $route,string $bytes): void { $get=psaRequest($port,'GET',$route);psaExact($get,200,'text/css; charset=UTF-8',$bytes,'GET exact '.$route);$head=psaRequest($port,'HEAD',$route);assertSameValue([200,'text/css; charset=UTF-8',(string)strlen($bytes),''],[$head['status'],psaHeader($head,'content-type'),psaHeader($head,'content-length'),$head['body']],'HEAD exact '.$route);psaSecurity($head,'HEAD exact '.$route); }
function psaError(array $r,int $status,string $why,array $extra=[]): void { $body=$status===503?"Service unavailable.\n":($status===405?"Method not allowed.\n":"Not found.\n");psaExact($r,$status,'text/plain; charset=UTF-8',$body,$why,$extra);foreach(['PRIVATE-UNREFERENCED','SECRET-OUTSIDE','ATTACKER-REPLACEMENT','/home/','Exception','stack trace']as$secret)assertSameValue(false,str_contains($r['body'],$secret),$why.' redaction'); }
function psaWriteGraph(string $root,array $files): string { foreach($files as$relative=>$bytes){$path=$root.'/'.$relative;if(!is_dir(dirname($path)))mkdir(dirname($path),0700,true);file_put_contents($path,$bytes);}return $root.'/shlz.css'; }
function psaRemoveTree(string $root): void { if(!is_dir($root))return;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as$f){$p=$f->getPathname();if($f->isLink()||$f->isFile())unlink($p);else rmdir($p);}rmdir($root); }

