 foreach(["@import url(\"unterminated.css);\n", "\xFF\xFE", "@import \"pilot.css\";\n"]as$i=>$bad){$root=$base.'/malformed-'.$i;mkdir($root,0700);psaWriteGraph($root,['shlz.css'=>$bad,'pilot.css'=>'COLLISION']);$s=psaStart($root.'/shlz.css');psaError(psaRequest($s['port'],'GET','/pilot/assets/shlz.css'),503,'malformed/collision graph '.$i,['retry-after'=>'60']);psaStop($s);}
